1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"strings"
9		"time"
10	
11		"github.com/go-git/go-git/v6"
12		"github.com/go-git/go-git/v6/plumbing"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agentimport"
15		"github.com/entireio/cli/cmd/entire/cli/auth"
16		"github.com/entireio/cli/cmd/entire/cli/gitremote"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/onboarding"
19		"github.com/entireio/cli/cmd/entire/cli/paths"
20		"github.com/entireio/cli/internal/coreapi"
21		"github.com/entireio/cli/internal/entireclient/contexts"
22	)
23	
24	// mirrorProbeTimeout bounds the control-plane round-trip when `entire status`
25	// or `entire enable` checks whether this repo is mirrored, so an offline
26	// terminal degrades to StateUnknown instead of hanging.
27	const mirrorProbeTimeout = 5 * time.Second
28	
29	// onboardingRungDeps carries the ground-truth probes the setup rungs check.
30	// Production wiring lives in newOnboardingRungDeps; tests inject fakes so rung
31	// logic runs without keyring, network, or filesystem access.
32	type onboardingRungDeps struct {
33		installedAgents func(ctx context.Context) []string
34		envToken        func() string
35		listContexts    func() ([]*contexts.Context, string, error)
36		tokenForContext func(c *contexts.Context) (string, error)
37		// resolveOrigin parses the origin remote into (forge, owner, repo);
38		// forge is "gh" for github.com (gitremote.ResolveRemoteRepo semantics).
39		resolveOrigin func(ctx context.Context) (forge, owner, repo string, err error)
40		// authed reports whether a usable login exists, without prompting.
41		authed func(ctx context.Context) bool
42		// probeMirror reports whether owner/repo is mirrored on any reachable
43		// core, and whether that mirror is suspended (production: cached,
44		// multi-core — see probeRepoMirrored).
45		probeMirror func(ctx context.Context, owner, repo string) (mirrorProbeResult, error)
46		// discoverImports reports per-agent local history discoverable for this
47		// repo and how much of it has not been imported yet. Local-only.
48		discoverImports func(ctx context.Context) ([]agentImportStatus, error)
49	}
50	
51	// agentImportStatus summarizes one agent's importable history for this repo.
52	type agentImportStatus struct {
53		Agent string `json:"agent"`
54		// Sessions is every discovered session, imported or not.
55		Sessions        int `json:"sessions"`
56		UnimportedTurns int `json:"unimported_turns"`
57		ImportedTurns   int `json:"imported_turns"`
58	}
59	
60	// newOnboardingRungDeps wires the rung probes to their real backends: agent
61	// hook detection, the stored auth context (offline — deliberately not
62	// RefreshedLoginToken, which can hit the network), origin parsing, the
63	// control-plane mirror list, and local agent-transcript discovery.
64	func newOnboardingRungDeps() onboardingRungDeps {
65		deps := onboardingRungDeps{
66			installedAgents: InstalledAgentDisplayNames,
67			envToken:        func() string { return os.Getenv(auth.EnvTokenVar) },
68			listContexts:    auth.Contexts,
69			tokenForContext: auth.LoginTokenForContext,
70			resolveOrigin: func(ctx context.Context) (string, string, string, error) {
71				return gitremote.ResolveRemoteRepo(ctx, "origin")
72			},
73			probeMirror:     probeRepoMirrored,
74			discoverImports: discoverAgentImports,
75		}
76		deps.authed = func(ctx context.Context) bool {
77			return authRung(deps).Check(ctx).State == onboarding.StateDone
78		}
79		return deps
80	}
81	
82	// onboardingLadder is the canonical setup ladder, in offer order.
83	func onboardingLadder(deps onboardingRungDeps) onboarding.Ladder {
84		return onboarding.Ladder{hooksRung(deps), authRung(deps), mirrorRung(deps), importRung(deps)}
85	}
86	
87	// githubSlug is the single encoding of the "server-side mirror slugs are
88	// lowercase" invariant (parseGitHubURL semantics) — used for probe queries,
89	// the probe-cache key, and the create write-through, which must never fork
90	// on case.
91	func githubSlug(owner, repo string) (slugOwner, slugRepo string) {
92		return strings.ToLower(owner), strings.ToLower(repo)
93	}
94	
95	// availableMirrorLister is the subset of *coreapi.Client's methods the mirror
96	// probe needs; a seam so probeMirrorAcross is testable without a control plane.
97	type mirrorProbeClient interface {
98		ListAvailableMirrors(ctx context.Context, params coreapi.ListAvailableMirrorsParams) (*coreapi.ListAvailableMirrorsOutputBody, error)
99		mirrorLister
100		CoreOrigin() string
101	}
102	
103	// mirrorProbeResult is the mirror rung's ground truth. Mirrored alone is not
104	// "done": a registered placement can be admin-suspended, in which case it
105	// never serves and recovery is operator-side.
106	type mirrorProbeResult struct {
107		Mirrored  bool
108		Suspended bool
109	}
110	
111	// probeMirrorAcross asks each distinct core (deduped by origin) whether
112	// owner/repo is mirrored. A mirror found on any core counts: the active
113	// context's core and the default cluster the create offer targets can front
114	// different federations, and a mirror created on one is invisible to the
115	// other — probing only one would leave the rung re-offering creation
116	// forever. Errors matter only when every core is unreachable.
117	func probeMirrorAcross(ctx context.Context, clients []mirrorProbeClient, owner, repo string) (mirrorProbeResult, error) {
118		seen := map[string]bool{}
119		var lastErr error
120		answered := false
121		for _, client := range clients {
122			if client == nil || seen[client.CoreOrigin()] {
123				continue
124			}
125			seen[client.CoreOrigin()] = true
126			out, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{
127				Owner: coreapi.NewOptString(owner),
128			})
129			if err != nil {
130				lastErr = err
131				continue
132			}
133			answered = true
134			for _, m := range out.Available {
135				if strings.EqualFold(m.Owner, owner) && strings.EqualFold(m.Repo, repo) &&
136					m.Status == coreapi.AvailableMirrorStatusMirrored {
137					return mirrorProbeResult{
138						Mirrored:  true,
139						Suspended: mirrorSuspendedOn(ctx, client, owner, repo),
140					}, nil
141				}
142			}
143		}
144		if !answered {
145			if lastErr == nil {
146				lastErr = errors.New("no control-plane core reachable")
147			}
148			return mirrorProbeResult{}, fmt.Errorf("probe mirrors: %w", lastErr)
149		}
150		return mirrorProbeResult{}, nil
151	}
152	
153	// mirrorSuspendedOn reports whether every placement of owner/repo visible on
154	// this core is suspended. ListAvailableMirrors cannot express suspension —
155	// its status enum stops at "mirrored" — so a suspended placement reads as
156	// mirrored there; this follow-up read of the mirrors themselves keeps the
157	// checklist from showing a green rung for a mirror that will never serve.
158	// Best-effort and fail-open: an error, an absent status, or a listing that
159	// doesn't surface the placement all count as not suspended, so the probe's
160	// mirrored answer never degrades.
161	func mirrorSuspendedOn(ctx context.Context, client mirrorLister, owner, repo string) bool {
162		mirrors, err := listMirrorsForRepo(ctx, client, mirrorCloneProviderGitHub, owner, repo)
163		if err != nil {
164			logging.Debug(ctx, "onboarding: mirror suspension check failed", "error", err)
165			return false
166		}
167		if len(mirrors) == 0 {
168			return false
169		}
170		for _, m := range mirrors {
171			if m.Status.Or("") != coreapi.MirrorStatusSuspended {
172				return false
173			}
174		}
175		return true
176	}
177	
178	// probeRepoMirrored checks whether owner/repo has a mirror on the active
179	// context's core or the default cluster's core, consulting a short-TTL
180	// per-user cache first so hot paths (`entire status`) don't pay a network
181	// round-trip on every run. Failures are cached briefly too, so an offline
182	// terminal doesn't hang on every invocation. Owner/repo arrive lowercased
183	// from the mirror rung.
184	func probeRepoMirrored(ctx context.Context, owner, repo string) (mirrorProbeResult, error) {
185		slug := owner + "/" + repo
186		cache := defaultMirrorProbeCache()
187		now := time.Now()
188		if probe, unreachable, ok := cache.get(slug, now); ok {
189			if unreachable {
190				return mirrorProbeResult{}, errors.New("control plane unreachable (cached)")
191			}
192			return probe, nil
193		}
194		ctx, cancel := context.WithTimeout(ctx, mirrorProbeTimeout)
195		defer cancel()
196		var clients []mirrorProbeClient
197		if activeCore, err := coreapi.New(); err == nil {
198			clients = append(clients, activeCore)
199		}
200		if clusterCore, err := coreapi.NewForCluster(ctx, defaultClusterHost); err == nil {
201			clients = append(clients, clusterCore)
202		}
203		probe, err := probeMirrorAcross(ctx, clients, owner, repo)
204		if err != nil {
205			cache.putUnreachable(slug, now)
206			return mirrorProbeResult{}, err
207		}
208		cache.put(slug, probe, now)
209		return probe, nil
210	}
211	
212	// discoverAgentImports reports, per registered importer, how much local
213	// transcript history exists for this repo and how much of it has never been
214	// imported. Discovery is file globbing; the expensive dry-run (checkpoint
215	// store open + transcript parsing) is memoized behind a fingerprint of the
216	// discovered files and the metadata-branch tip, so an unchanged repo pays
217	// only the glob on hot paths like `entire status`. Local-only, best-effort
218	// per agent.
219	func discoverAgentImports(ctx context.Context) ([]agentImportStatus, error) {
220		repoRoot, err := paths.WorktreeRoot(ctx)
221		if err != nil {
222			return nil, fmt.Errorf("resolve worktree root: %w", err)
223		}
224		now := time.Now()
225		type discovery struct {
226			imp   agentimport.Importer
227			files []agentimport.SessionFile
228		}
229		var discovered []discovery
230		var inputs []importScanInput
231		cacheable := true
232		discoverFailures := 0
233		// Scope to agents with hooks installed — the same set the import offer
234		// acts on. Iterating every registered importer would report Missing for
235		// history the offer will never import, an unresolvable checklist row.
236		for _, ag := range installedImportAgents(ctx) {
237			imp := importerForAgent(ag)
238			if imp == nil {
239				continue
240			}
241			files, discoverErr := imp.Discover(repoRoot, "", now, nil)
242			if discoverErr != nil {
243				// Best-effort per agent, but an error is not "nothing found":
244				// don't memoize a result computed without this agent's files.
245				logging.Warn(ctx, "onboarding: transcript discovery failed", "agent", imp.Name(), "error", discoverErr)
246				discoverFailures++
247				cacheable = false
248				continue
249			}
250			if len(files) == 0 {
251				continue
252			}
253			discovered = append(discovered, discovery{imp: imp, files: files})
254			for _, f := range files {
255				info, statErr := os.Stat(f.Path)
256				if statErr != nil {
257					// A file vanished between glob and stat — don't trust a
258					// fingerprint built from a moving target.
259					cacheable = false
260					continue
261				}
262				inputs = append(inputs, importScanInput{Path: f.Path, ModTime: info.ModTime(), Size: info.Size()})
263			}
264		}
265		if len(discovered) == 0 {
266			if discoverFailures > 0 {
267				// Every answer we have is an error — "no prior history found"
268				// would be an affirmatively false settled state.
269				return nil, fmt.Errorf("transcript discovery failed for %d agent(s)", discoverFailures)
270			}
271			return nil, nil
272		}
273	
274		repo, err := openRepository(ctx)
275		if err != nil {
276			return nil, err
277		}
278		defer repo.Close()
279	
280		// The offer's import runner refuses to write under a restrictive
281		// checkpoint policy; the rung must agree, or it reports Missing forever
282		// while every consented offer silently skips.
283		if policyErr := ensureCheckpointPolicyAllowsCheckpointData(ctx, repo); policyErr != nil {
284			return nil, fmt.Errorf("%w: %w", errImportsPolicyRestricted, policyErr)
285		}
286	
287		fingerprint := importScanFingerprint(inputs, metadataBranchTip(repo))
288		cache := defaultImportScanCache()
289		if cacheable {
290			if statuses, ok := cache.get(repoRoot, fingerprint); ok {
291				return statuses, nil
292			}
293		}
294	
295		var statuses []agentImportStatus
296		runFailures := 0
297		for _, d := range discovered {
298			res, runErr := agentimport.Run(ctx, repo, d.imp, agentimport.Options{
299				RepoRoot: repoRoot, Now: now, DryRun: true,
300			})
301			if runErr != nil {
302				// Best-effort per agent, but a partial result must not be
303				// memoized — it would stay wrong until the fingerprint moves.
304				logging.Warn(ctx, "onboarding: import dry-run failed", "agent", d.imp.Name(), "error", runErr)
305				runFailures++
306				cacheable = false
307				continue
308			}
309			statuses = append(statuses, agentImportStatus{
310				Agent:           d.imp.Name(),
311				Sessions:        res.SessionsScanned,
312				UnimportedTurns: res.TurnsImported,
313				ImportedTurns:   res.TurnsSkipped,
314			})
315		}
316		if runFailures == len(discovered) {
317			// Every scan failed (typically one repo-level cause): report the
318			// failure so the rung renders Unknown instead of a false
319			// "no prior history found" / "N sessions imported".
320			return nil, fmt.Errorf("import scan failed for all %d agent(s) with history", runFailures)
321		}
322		if cacheable {
323			cache.put(repoRoot, fingerprint, statuses)
324		}
325		return statuses, nil
326	}
327	
328	// metadataBranchTip identifies the local checkpoint-metadata state for the
329	// import-scan fingerprint: any new checkpoint or import moves the ref.
330	func metadataBranchTip(repo *git.Repository) string {
331		ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
332		if err != nil {
333			return "none"
334		}
335		return ref.Hash().String()
336	}
337	
338	func hooksRung(deps onboardingRungDeps) onboarding.Rung {
339		return onboarding.Rung{
340			Key:   onboarding.KeyHooks,
341			Title: "Agent hooks",
342			Check: func(ctx context.Context) onboarding.Check {
343				agents := deps.installedAgents(ctx)
344				if len(agents) == 0 {
345					return onboarding.Check{State: onboarding.StateMissing, Hint: "entire enable"}
346				}
347				return onboarding.Check{State: onboarding.StateDone, Detail: strings.Join(agents, ", ")}
348			},
349		}
350	}
351	
352	func mirrorRung(deps onboardingRungDeps) onboarding.Rung {
353		return onboarding.Rung{
354			Key:   onboarding.KeyMirror,
355			Title: "Repo mirrored",
356			Check: func(ctx context.Context) onboarding.Check {
357				forge, owner, repo, err := deps.resolveOrigin(ctx)
358				if err != nil {
359					// A resolution failure (git exec error, canceled context) is
360					// not the same fact as "this repo isn't on GitHub".
361					logging.Debug(ctx, "onboarding: origin resolution failed", "error", err)
362					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
363				}
364				if forge != "gh" {
365					return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no GitHub origin"}
366				}
367				owner, repo = githubSlug(owner, repo)
368				slug := "github.com/" + owner + "/" + repo
369				if !deps.authed(ctx) {
370					return onboarding.Check{
371						State:  onboarding.StateBlocked,
372						Detail: "needs login",
373						Hint:   "entire auth login",
374					}
375				}
376				probe, err := deps.probeMirror(ctx, owner, repo)
377				if err != nil {
378					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
379				}
380				if probe.Mirrored && probe.Suspended {
381					// Registered but admin-suspended: it never serves, and
382					// re-creating cannot fix it — recovery is operator-side.
383					// Blocked keeps the checklist honest without re-offering.
384					return onboarding.Check{
385						State:  onboarding.StateBlocked,
386						Detail: "mirror suspended by an admin",
387						Hint:   "entire repo mirror list",
388					}
389				}
390				if probe.Mirrored {
391					return onboarding.Check{State: onboarding.StateDone, Detail: slug}
392				}
393				return onboarding.Check{
394					State:  onboarding.StateMissing,
395					Detail: "commits won't appear in the web UI",
396					Hint:   "entire repo mirror create " + slug,
397				}
398			},
399		}
400	}
401	
402	// errImportsPolicyRestricted marks a repo whose checkpoint policy forbids
403	// writing checkpoint data: importing is impossible here, not pending.
404	var errImportsPolicyRestricted = errors.New("checkpoint policy restricts imported history")
405	
406	func importRung(deps onboardingRungDeps) onboarding.Rung {
407		return onboarding.Rung{
408			Key:   onboarding.KeyImport,
409			Title: "History",
410			Check: func(ctx context.Context) onboarding.Check {
411				statuses, err := deps.discoverImports(ctx)
412				if errors.Is(err, errImportsPolicyRestricted) {
413					return onboarding.Check{
414						State:  onboarding.StateNotApplicable,
415						Detail: "imports restricted by checkpoint policy",
416					}
417				}
418				if err != nil {
419					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire import"}
420				}
421				totalSessions := 0
422				var unimported []agentImportStatus
423				for _, s := range statuses {
424					totalSessions += s.Sessions
425					if s.UnimportedTurns > 0 {
426						unimported = append(unimported, s)
427					}
428				}
429				if totalSessions == 0 {
430					return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no prior history found"}
431				}
432				if len(unimported) == 0 {
433					return onboarding.Check{
434						State:  onboarding.StateDone,
435						Detail: fmt.Sprintf("%d sessions imported", totalSessions),
436					}
437				}
438				return onboarding.Check{
439					State:  onboarding.StateMissing,
440					Detail: unimportedDetail(unimported),
441					Hint:   "entire import " + unimported[0].Agent,
442				}
443			},
444		}
445	}
446	
447	// unimportedDetail phrases the import rung's remaining work. When nothing was
448	// ever imported, session counts are accurate ("12 claude-code sessions found,
449	// not imported"). After a partial import, claiming every discovered session is
450	// unimported would overstate the work, so the wording switches to pending
451	// turns.
452	func unimportedDetail(unimported []agentImportStatus) string {
453		agents := make([]string, 0, len(unimported))
454		parts := make([]string, 0, len(unimported))
455		sessions, pendingTurns, importedTurns := 0, 0, 0
456		for _, s := range unimported {
457			agents = append(agents, s.Agent)
458			parts = append(parts, fmt.Sprintf("%d %s", s.Sessions, s.Agent))
459			sessions += s.Sessions
460			pendingTurns += s.UnimportedTurns
461			importedTurns += s.ImportedTurns
462		}
463		if importedTurns > 0 {
464			noun := "turns"
465			if pendingTurns == 1 {
466				noun = "turn"
467			}
468			return fmt.Sprintf("%s history partially imported (%d %s pending)",
469				strings.Join(agents, ", "), pendingTurns, noun)
470		}
471		if sessions == 1 {
472			return strings.Join(parts, ", ") + " session found, not imported"
473		}
474		return strings.Join(parts, ", ") + " sessions found, not imported"
475	}
476	
477	func authRung(deps onboardingRungDeps) onboarding.Rung {
478		return onboarding.Rung{
479			Key:   onboarding.KeyAuth,
480			Title: "Logged in",
481			Check: func(ctx context.Context) onboarding.Check {
482				if deps.envToken() != "" {
483					return onboarding.Check{State: onboarding.StateDone, Detail: "using ENTIRE_TOKEN"}
484				}
485				ctxs, current, err := deps.listContexts()
486				if err != nil {
487					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire auth status"}
488				}
489				for _, c := range ctxs {
490					if c.Name != current {
491						continue
492					}
493					token, tokenErr := deps.tokenForContext(c)
494					if tokenErr != nil {
495						// A keyring/token-store failure is infrastructure, not
496						// "not logged in" — offering a browser login would fail
497						// against the same broken store.
498						logging.Warn(ctx, "onboarding: token store unreadable", "context", c.Name, "error", tokenErr)
499						return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire auth status"}
500					}
501					if token != "" {
502						return onboarding.Check{State: onboarding.StateDone, Detail: c.Handle}
503					}
504					break
505				}
506				return onboarding.Check{State: onboarding.StateMissing, Hint: "entire auth login"}
507			},
508		}
509	}
