package cli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/agentimport"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/onboarding"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/internal/coreapi"
	"github.com/entireio/cli/internal/entireclient/contexts"
)

// mirrorProbeTimeout bounds the control-plane round-trip when `entire status`
// or `entire enable` checks whether this repo is mirrored, so an offline
// terminal degrades to StateUnknown instead of hanging.
const mirrorProbeTimeout = 5 * time.Second

// onboardingRungDeps carries the ground-truth probes the setup rungs check.
// Production wiring lives in newOnboardingRungDeps; tests inject fakes so rung
// logic runs without keyring, network, or filesystem access.
type onboardingRungDeps struct {
	installedAgents func(ctx context.Context) []string
	envToken        func() string
	listContexts    func() ([]*contexts.Context, string, error)
	tokenForContext func(c *contexts.Context) (string, error)
	// resolveOrigin parses the origin remote into (forge, owner, repo);
	// forge is "gh" for github.com (gitremote.ResolveRemoteRepo semantics).
	resolveOrigin func(ctx context.Context) (forge, owner, repo string, err error)
	// authed reports whether a usable login exists, without prompting.
	authed func(ctx context.Context) bool
	// probeMirror reports whether owner/repo is mirrored on any reachable
	// core, and whether that mirror is suspended (production: cached,
	// multi-core — see probeRepoMirrored).
	probeMirror func(ctx context.Context, owner, repo string) (mirrorProbeResult, error)
	// discoverImports reports per-agent local history discoverable for this
	// repo and how much of it has not been imported yet. Local-only.
	discoverImports func(ctx context.Context) ([]agentImportStatus, error)
}

// agentImportStatus summarizes one agent's importable history for this repo.
type agentImportStatus struct {
	Agent string `json:"agent"`
	// Sessions is every discovered session, imported or not.
	Sessions        int `json:"sessions"`
	UnimportedTurns int `json:"unimported_turns"`
	ImportedTurns   int `json:"imported_turns"`
}

// newOnboardingRungDeps wires the rung probes to their real backends: agent
// hook detection, the stored auth context (offline — deliberately not
// RefreshedLoginToken, which can hit the network), origin parsing, the
// control-plane mirror list, and local agent-transcript discovery.
func newOnboardingRungDeps() onboardingRungDeps {
	deps := onboardingRungDeps{
		installedAgents: InstalledAgentDisplayNames,
		envToken:        func() string { return os.Getenv(auth.EnvTokenVar) },
		listContexts:    auth.Contexts,
		tokenForContext: auth.LoginTokenForContext,
		resolveOrigin: func(ctx context.Context) (string, string, string, error) {
			return gitremote.ResolveRemoteRepo(ctx, "origin")
		},
		probeMirror:     probeRepoMirrored,
		discoverImports: discoverAgentImports,
	}
	deps.authed = func(ctx context.Context) bool {
		return authRung(deps).Check(ctx).State == onboarding.StateDone
	}
	return deps
}

// onboardingLadder is the canonical setup ladder, in offer order.
func onboardingLadder(deps onboardingRungDeps) onboarding.Ladder {
	return onboarding.Ladder{hooksRung(deps), authRung(deps), mirrorRung(deps), importRung(deps)}
}

// githubSlug is the single encoding of the "server-side mirror slugs are
// lowercase" invariant (parseGitHubURL semantics) — used for probe queries,
// the probe-cache key, and the create write-through, which must never fork
// on case.
func githubSlug(owner, repo string) (slugOwner, slugRepo string) {
	return strings.ToLower(owner), strings.ToLower(repo)
}

// availableMirrorLister is the subset of *coreapi.Client's methods the mirror
// probe needs; a seam so probeMirrorAcross is testable without a control plane.
type mirrorProbeClient interface {
	ListAvailableMirrors(ctx context.Context, params coreapi.ListAvailableMirrorsParams) (*coreapi.ListAvailableMirrorsOutputBody, error)
	mirrorLister
	CoreOrigin() string
}

// mirrorProbeResult is the mirror rung's ground truth. Mirrored alone is not
// "done": a registered placement can be admin-suspended, in which case it
// never serves and recovery is operator-side.
type mirrorProbeResult struct {
	Mirrored  bool
	Suspended bool
}

// probeMirrorAcross asks each distinct core (deduped by origin) whether
// owner/repo is mirrored. A mirror found on any core counts: the active
// context's core and the default cluster the create offer targets can front
// different federations, and a mirror created on one is invisible to the
// other — probing only one would leave the rung re-offering creation
// forever. Errors matter only when every core is unreachable.
func probeMirrorAcross(ctx context.Context, clients []mirrorProbeClient, owner, repo string) (mirrorProbeResult, error) {
	seen := map[string]bool{}
	var lastErr error
	answered := false
	for _, client := range clients {
		if client == nil || seen[client.CoreOrigin()] {
			continue
		}
		seen[client.CoreOrigin()] = true
		out, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{
			Owner: coreapi.NewOptString(owner),
		})
		if err != nil {
			lastErr = err
			continue
		}
		answered = true
		for _, m := range out.Available {
			if strings.EqualFold(m.Owner, owner) && strings.EqualFold(m.Repo, repo) &&
				m.Status == coreapi.AvailableMirrorStatusMirrored {
				return mirrorProbeResult{
					Mirrored:  true,
					Suspended: mirrorSuspendedOn(ctx, client, owner, repo),
				}, nil
			}
		}
	}
	if !answered {
		if lastErr == nil {
			lastErr = errors.New("no control-plane core reachable")
		}
		return mirrorProbeResult{}, fmt.Errorf("probe mirrors: %w", lastErr)
	}
	return mirrorProbeResult{}, nil
}

// mirrorSuspendedOn reports whether every placement of owner/repo visible on
// this core is suspended. ListAvailableMirrors cannot express suspension —
// its status enum stops at "mirrored" — so a suspended placement reads as
// mirrored there; this follow-up read of the mirrors themselves keeps the
// checklist from showing a green rung for a mirror that will never serve.
// Best-effort and fail-open: an error, an absent status, or a listing that
// doesn't surface the placement all count as not suspended, so the probe's
// mirrored answer never degrades.
func mirrorSuspendedOn(ctx context.Context, client mirrorLister, owner, repo string) bool {
	mirrors, err := listMirrorsForRepo(ctx, client, mirrorCloneProviderGitHub, owner, repo)
	if err != nil {
		logging.Debug(ctx, "onboarding: mirror suspension check failed", "error", err)
		return false
	}
	if len(mirrors) == 0 {
		return false
	}
	for _, m := range mirrors {
		if m.Status.Or("") != coreapi.MirrorStatusSuspended {
			return false
		}
	}
	return true
}

// probeRepoMirrored checks whether owner/repo has a mirror on the active
// context's core or the default cluster's core, consulting a short-TTL
// per-user cache first so hot paths (`entire status`) don't pay a network
// round-trip on every run. Failures are cached briefly too, so an offline
// terminal doesn't hang on every invocation. Owner/repo arrive lowercased
// from the mirror rung.
func probeRepoMirrored(ctx context.Context, owner, repo string) (mirrorProbeResult, error) {
	slug := owner + "/" + repo
	cache := defaultMirrorProbeCache()
	now := time.Now()
	if probe, unreachable, ok := cache.get(slug, now); ok {
		if unreachable {
			return mirrorProbeResult{}, errors.New("control plane unreachable (cached)")
		}
		return probe, nil
	}
	ctx, cancel := context.WithTimeout(ctx, mirrorProbeTimeout)
	defer cancel()
	var clients []mirrorProbeClient
	if activeCore, err := coreapi.New(); err == nil {
		clients = append(clients, activeCore)
	}
	if clusterCore, err := coreapi.NewForCluster(ctx, defaultClusterHost); err == nil {
		clients = append(clients, clusterCore)
	}
	probe, err := probeMirrorAcross(ctx, clients, owner, repo)
	if err != nil {
		cache.putUnreachable(slug, now)
		return mirrorProbeResult{}, err
	}
	cache.put(slug, probe, now)
	return probe, nil
}

// discoverAgentImports reports, per registered importer, how much local
// transcript history exists for this repo and how much of it has never been
// imported. Discovery is file globbing; the expensive dry-run (checkpoint
// store open + transcript parsing) is memoized behind a fingerprint of the
// discovered files and the metadata-branch tip, so an unchanged repo pays
// only the glob on hot paths like `entire status`. Local-only, best-effort
// per agent.
func discoverAgentImports(ctx context.Context) ([]agentImportStatus, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}
	now := time.Now()
	type discovery struct {
		imp   agentimport.Importer
		files []agentimport.SessionFile
	}
	var discovered []discovery
	var inputs []importScanInput
	cacheable := true
	discoverFailures := 0
	// Scope to agents with hooks installed — the same set the import offer
	// acts on. Iterating every registered importer would report Missing for
	// history the offer will never import, an unresolvable checklist row.
	for _, ag := range installedImportAgents(ctx) {
		imp := importerForAgent(ag)
		if imp == nil {
			continue
		}
		files, discoverErr := imp.Discover(repoRoot, "", now, nil)
		if discoverErr != nil {
			// Best-effort per agent, but an error is not "nothing found":
			// don't memoize a result computed without this agent's files.
			logging.Warn(ctx, "onboarding: transcript discovery failed", "agent", imp.Name(), "error", discoverErr)
			discoverFailures++
			cacheable = false
			continue
		}
		if len(files) == 0 {
			continue
		}
		discovered = append(discovered, discovery{imp: imp, files: files})
		for _, f := range files {
			info, statErr := os.Stat(f.Path)
			if statErr != nil {
				// A file vanished between glob and stat — don't trust a
				// fingerprint built from a moving target.
				cacheable = false
				continue
			}
			inputs = append(inputs, importScanInput{Path: f.Path, ModTime: info.ModTime(), Size: info.Size()})
		}
	}
	if len(discovered) == 0 {
		if discoverFailures > 0 {
			// Every answer we have is an error — "no prior history found"
			// would be an affirmatively false settled state.
			return nil, fmt.Errorf("transcript discovery failed for %d agent(s)", discoverFailures)
		}
		return nil, nil
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return nil, err
	}
	defer repo.Close()

	// The offer's import runner refuses to write under a restrictive
	// checkpoint policy; the rung must agree, or it reports Missing forever
	// while every consented offer silently skips.
	if policyErr := ensureCheckpointPolicyAllowsCheckpointData(ctx, repo); policyErr != nil {
		return nil, fmt.Errorf("%w: %w", errImportsPolicyRestricted, policyErr)
	}

	fingerprint := importScanFingerprint(inputs, metadataBranchTip(repo))
	cache := defaultImportScanCache()
	if cacheable {
		if statuses, ok := cache.get(repoRoot, fingerprint); ok {
			return statuses, nil
		}
	}

	var statuses []agentImportStatus
	runFailures := 0
	for _, d := range discovered {
		res, runErr := agentimport.Run(ctx, repo, d.imp, agentimport.Options{
			RepoRoot: repoRoot, Now: now, DryRun: true,
		})
		if runErr != nil {
			// Best-effort per agent, but a partial result must not be
			// memoized — it would stay wrong until the fingerprint moves.
			logging.Warn(ctx, "onboarding: import dry-run failed", "agent", d.imp.Name(), "error", runErr)
			runFailures++
			cacheable = false
			continue
		}
		statuses = append(statuses, agentImportStatus{
			Agent:           d.imp.Name(),
			Sessions:        res.SessionsScanned,
			UnimportedTurns: res.TurnsImported,
			ImportedTurns:   res.TurnsSkipped,
		})
	}
	if runFailures == len(discovered) {
		// Every scan failed (typically one repo-level cause): report the
		// failure so the rung renders Unknown instead of a false
		// "no prior history found" / "N sessions imported".
		return nil, fmt.Errorf("import scan failed for all %d agent(s) with history", runFailures)
	}
	if cacheable {
		cache.put(repoRoot, fingerprint, statuses)
	}
	return statuses, nil
}

// metadataBranchTip identifies the local checkpoint-metadata state for the
// import-scan fingerprint: any new checkpoint or import moves the ref.
func metadataBranchTip(repo *git.Repository) string {
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return "none"
	}
	return ref.Hash().String()
}

func hooksRung(deps onboardingRungDeps) onboarding.Rung {
	return onboarding.Rung{
		Key:   onboarding.KeyHooks,
		Title: "Agent hooks",
		Check: func(ctx context.Context) onboarding.Check {
			agents := deps.installedAgents(ctx)
			if len(agents) == 0 {
				return onboarding.Check{State: onboarding.StateMissing, Hint: "entire enable"}
			}
			return onboarding.Check{State: onboarding.StateDone, Detail: strings.Join(agents, ", ")}
		},
	}
}

func mirrorRung(deps onboardingRungDeps) onboarding.Rung {
	return onboarding.Rung{
		Key:   onboarding.KeyMirror,
		Title: "Repo mirrored",
		Check: func(ctx context.Context) onboarding.Check {
			forge, owner, repo, err := deps.resolveOrigin(ctx)
			if err != nil {
				// A resolution failure (git exec error, canceled context) is
				// not the same fact as "this repo isn't on GitHub".
				logging.Debug(ctx, "onboarding: origin resolution failed", "error", err)
				return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
			}
			if forge != "gh" {
				return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no GitHub origin"}
			}
			owner, repo = githubSlug(owner, repo)
			slug := "github.com/" + owner + "/" + repo
			if !deps.authed(ctx) {
				return onboarding.Check{
					State:  onboarding.StateBlocked,
					Detail: "needs login",
					Hint:   "entire auth login",
				}
			}
			probe, err := deps.probeMirror(ctx, owner, repo)
			if err != nil {
				return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
			}
			if probe.Mirrored && probe.Suspended {
				// Registered but admin-suspended: it never serves, and
				// re-creating cannot fix it — recovery is operator-side.
				// Blocked keeps the checklist honest without re-offering.
				return onboarding.Check{
					State:  onboarding.StateBlocked,
					Detail: "mirror suspended by an admin",
					Hint:   "entire repo mirror list",
				}
			}
			if probe.Mirrored {
				return onboarding.Check{State: onboarding.StateDone, Detail: slug}
			}
			return onboarding.Check{
				State:  onboarding.StateMissing,
				Detail: "commits won't appear in the web UI",
				Hint:   "entire repo mirror create " + slug,
			}
		},
	}
}

// errImportsPolicyRestricted marks a repo whose checkpoint policy forbids
// writing checkpoint data: importing is impossible here, not pending.
var errImportsPolicyRestricted = errors.New("checkpoint policy restricts imported history")

func importRung(deps onboardingRungDeps) onboarding.Rung {
	return onboarding.Rung{
		Key:   onboarding.KeyImport,
		Title: "History",
		Check: func(ctx context.Context) onboarding.Check {
			statuses, err := deps.discoverImports(ctx)
			if errors.Is(err, errImportsPolicyRestricted) {
				return onboarding.Check{
					State:  onboarding.StateNotApplicable,
					Detail: "imports restricted by checkpoint policy",
				}
			}
			if err != nil {
				return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire import"}
			}
			totalSessions := 0
			var unimported []agentImportStatus
			for _, s := range statuses {
				totalSessions += s.Sessions
				if s.UnimportedTurns > 0 {
					unimported = append(unimported, s)
				}
			}
			if totalSessions == 0 {
				return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no prior history found"}
			}
			if len(unimported) == 0 {
				return onboarding.Check{
					State:  onboarding.StateDone,
					Detail: fmt.Sprintf("%d sessions imported", totalSessions),
				}
			}
			return onboarding.Check{
				State:  onboarding.StateMissing,
				Detail: unimportedDetail(unimported),
				Hint:   "entire import " + unimported[0].Agent,
			}
		},
	}
}

// unimportedDetail phrases the import rung's remaining work. When nothing was
// ever imported, session counts are accurate ("12 claude-code sessions found,
// not imported"). After a partial import, claiming every discovered session is
// unimported would overstate the work, so the wording switches to pending
// turns.
func unimportedDetail(unimported []agentImportStatus) string {
	agents := make([]string, 0, len(unimported))
	parts := make([]string, 0, len(unimported))
	sessions, pendingTurns, importedTurns := 0, 0, 0
	for _, s := range unimported {
		agents = append(agents, s.Agent)
		parts = append(parts, fmt.Sprintf("%d %s", s.Sessions, s.Agent))
		sessions += s.Sessions
		pendingTurns += s.UnimportedTurns
		importedTurns += s.ImportedTurns
	}
	if importedTurns > 0 {
		noun := "turns"
		if pendingTurns == 1 {
			noun = "turn"
		}
		return fmt.Sprintf("%s history partially imported (%d %s pending)",
			strings.Join(agents, ", "), pendingTurns, noun)
	}
	if sessions == 1 {
		return strings.Join(parts, ", ") + " session found, not imported"
	}
	return strings.Join(parts, ", ") + " sessions found, not imported"
}

func authRung(deps onboardingRungDeps) onboarding.Rung {
	return onboarding.Rung{
		Key:   onboarding.KeyAuth,
		Title: "Logged in",
		Check: func(ctx context.Context) onboarding.Check {
			if deps.envToken() != "" {
				return onboarding.Check{State: onboarding.StateDone, Detail: "using ENTIRE_TOKEN"}
			}
			ctxs, current, err := deps.listContexts()
			if err != nil {
				return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire auth status"}
			}
			for _, c := range ctxs {
				if c.Name != current {
					continue
				}
				token, tokenErr := deps.tokenForContext(c)
				if tokenErr != nil {
					// A keyring/token-store failure is infrastructure, not
					// "not logged in" — offering a browser login would fail
					// against the same broken store.
					logging.Warn(ctx, "onboarding: token store unreadable", "context", c.Name, "error", tokenErr)
					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire auth status"}
				}
				if token != "" {
					return onboarding.Check{State: onboarding.StateDone, Detail: c.Handle}
				}
				break
			}
			return onboarding.Check{State: onboarding.StateMissing, Hint: "entire auth login"}
		},
	}
}

package cli

import (
	"context"
	"fmt"
	"io"
	"strings"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/onboarding"
)

// onboardingSetupMode is the answer to enable's single consent prompt.
type onboardingSetupMode int

const (
	// setupModeSkip declines the offers this once — tracking continues either
	// way; the closing checklist carries the run-later commands and re-running
	// enable re-offers whatever is still missing. Deliberately the zero value:
	// a forgotten or defaulted mode must never run login or mirror creation.
	setupModeSkip onboardingSetupMode = iota
	// setupModeAll runs every missing rung back-to-back without further questions.
	setupModeAll
	// setupModeStepByStep confirms each missing rung individually.
	setupModeStepByStep
)

// onboardingOfferRunner drives the connect rungs at the end of `entire
// enable`: one consent prompt, then offers for whatever is missing, then the
// closing checklist. Rung state is recomputed before each offer, so a login
// completed in this pass unblocks the mirror rung in the same pass, and a
// rung finished out-of-band is never re-offered — which is also what makes
// re-running `entire enable` the resume path after an interrupted setup.
// All fields are seams; newOnboardingOfferRunner wires production behavior.
type onboardingOfferRunner struct {
	deps onboardingRungDeps
	// offerFns runs a rung's setup step; granular=true (step-by-step mode)
	// lets an offer present its own finer-grained picker.
	offerFns map[string]func(ctx context.Context, granular bool) error
	// selfPrompting marks offers that present their own confirmation UI in
	// granular mode (the import picker), so runOffers skips the generic
	// yes/no confirm instead of asking twice.
	selfPrompting map[string]bool
	// autoRun marks rungs whose offer runs without a prompt when prompting is
	// unavailable — --yes ("accept all defaults") auto-imports, matching the
	// enable-time import contract; login/mirror are never implicit.
	autoRun     map[string]bool
	canPrompt   func() bool
	promptMode  func(ctx context.Context, missing []onboarding.Result) (onboardingSetupMode, error)
	confirmRung func(ctx context.Context, r onboarding.Result) (bool, error)
	styles      func(w io.Writer) statusStyles
}

func (r onboardingOfferRunner) run(ctx context.Context, w io.Writer) {
	ladder := onboardingLadder(r.deps)
	results := ladder.Checks(ctx)

	if actionable := r.offerable(results); len(actionable) > 0 && r.canPrompt() {
		mode, err := r.promptMode(ctx, actionable)
		if err != nil {
			// Cancelling the consent prompt (Ctrl-C) behaves like skip: enable
			// has already succeeded, so fall through to the checklist, whose
			// hints are the resume path. Logged so a broken terminal doesn't
			// masquerade as a user choice.
			logging.Debug(ctx, "onboarding: consent prompt did not complete", "error", err)
			mode = setupModeSkip
		}
		if mode != setupModeSkip {
			r.runOffers(ctx, w, ladder, mode)
			results = ladder.Checks(ctx)
		}
	} else if r.runAutoOffers(ctx, w, ladder) {
		results = ladder.Checks(ctx)
	}

	fmt.Fprint(w, r.renderChecklist(w, results))
}

// runAutoOffers runs the autoRun rungs' offers when the prompt path didn't
// execute (no TTY or --yes). Reports whether any offer ran.
func (r onboardingOfferRunner) runAutoOffers(ctx context.Context, w io.Writer, ladder onboarding.Ladder) bool {
	ran := false
	for _, rung := range ladder {
		offer := r.offerFns[rung.Key]
		if offer == nil || !r.autoRun[rung.Key] {
			continue
		}
		if rung.Check(ctx).State != onboarding.StateMissing {
			continue
		}
		ran = true
		if err := offer(ctx, false); err != nil {
			logging.Warn(ctx, "onboarding: auto offer failed", "rung", rung.Key, "error", err)
			fmt.Fprintf(w, "  %s setup didn't complete: %v\n", rung.Title, err)
		}
	}
	return ran
}

// offerable filters the remaining work down to rungs this runner can act on.
// Missing rungs with an offer always qualify. Blocked rungs qualify only when
// an offerable Missing rung precedes them in the ladder — an earlier offer in
// the same pass (login) can unblock them. Without that, the consent prompt
// would promise work that can never run (e.g. auth Unknown leaves mirror
// Blocked with nothing to unblock it).
func (r onboardingOfferRunner) offerable(results []onboarding.Result) []onboarding.Result {
	var actionable []onboarding.Result
	unblockPossible := false
	for _, res := range results {
		if res.Check.State == onboarding.StateMissing && r.offerFns[res.Rung.Key] != nil {
			actionable = append(actionable, res)
			unblockPossible = true
			continue
		}
		if res.Check.State == onboarding.StateBlocked && r.offerFns[res.Rung.Key] != nil && unblockPossible {
			actionable = append(actionable, res)
		}
	}
	return actionable
}

// runOffers walks the ladder in order, re-checking each rung immediately
// before its offer. Offers are best-effort: a failure prints a notice and
// the closing checklist keeps the retry hint, but enable never fails.
func (r onboardingOfferRunner) runOffers(ctx context.Context, w io.Writer, ladder onboarding.Ladder, mode onboardingSetupMode) {
	granular := mode == setupModeStepByStep
	for _, rung := range ladder {
		offer := r.offerFns[rung.Key]
		if offer == nil {
			continue
		}
		check := rung.Check(ctx)
		if check.State != onboarding.StateMissing {
			continue
		}
		if granular && !r.selfPrompting[rung.Key] {
			accepted, err := r.confirmRung(ctx, onboarding.Result{Rung: rung, Check: check})
			if err != nil {
				// A failed confirm (Ctrl-C, broken terminal, cancelled ctx)
				// means the user is bailing out — stop walking rungs instead
				// of surfacing every remaining prompt one Ctrl-C at a time.
				logging.Debug(ctx, "onboarding: rung confirm prompt did not complete; stopping offers", "rung", rung.Key, "error", err)
				return
			}
			if !accepted {
				continue
			}
		}
		if err := offer(ctx, granular); err != nil {
			logging.Warn(ctx, "onboarding: offer failed", "rung", rung.Key, "error", err)
			fmt.Fprintf(w, "  %s setup didn't complete: %v\n", rung.Title, err)
		}
	}
}

func (r onboardingOfferRunner) renderChecklist(w io.Writer, results []onboarding.Result) string {
	sty := r.styles(w)
	var b strings.Builder
	b.WriteString(renderOnboardingChecklist(results, sty))
	// One "run later" line per unique command, in ladder order — a blocked
	// rung whose fix is another rung's command (mirror needs login) must not
	// repeat it.
	seen := map[string]bool{}
	for _, res := range onboarding.Missing(results) {
		if res.Check.Hint == "" || seen[res.Check.Hint] {
			continue
		}
		seen[res.Check.Hint] = true
		fmt.Fprintf(&b, "  run later: %s\n", sty.render(sty.cyan, res.Check.Hint))
	}
	return b.String()
}

// enableOnboardingOpts carries the enable-path context the ladder needs.
type enableOnboardingOpts struct {
	// assumeYes: --yes, "accept all defaults" — suppresses prompts.
	assumeYes bool
	// neverPrompt: the --agent path's documented non-interactive contract —
	// suppresses prompts without auto-running anything.
	neverPrompt bool
	// firstRun gates --yes auto-import: on the very first enable, --yes
	// auto-imports (the enable-time import contract); on any later enable it
	// must not, because "unimported history exists" cannot distinguish "new
	// history" from "history the user explicitly declined to import".
	// Interactive re-enables still offer — consent is explicit there.
	firstRun bool
	// importScope narrows the import offer to specific agents (the
	// just-selected ones, or the --agent target). Nil means every agent
	// with hooks installed — the resume-path scope.
	importScope []agent.Agent
}

// newEnableOnboardingRunner applies enableOnboardingOpts to the production
// runner. Split from runEnableOnboarding so the option→runner mapping is
// unit-testable without network or keyring access.
func newEnableOnboardingRunner(w io.Writer, o enableOnboardingOpts) onboardingOfferRunner {
	r := newOnboardingOfferRunner(w, o.importScope)
	if o.assumeYes || o.neverPrompt {
		r.canPrompt = func() bool { return false }
	}
	if o.assumeYes && o.firstRun {
		// Import is local-only, so "accept all defaults" may run it without
		// a prompt; login and mirror are never implicit.
		r.autoRun = map[string]bool{onboarding.KeyImport: true}
	}
	return r
}

// runEnableOnboarding runs the connect ladder at the end of `entire enable`.
// Best-effort by design: onboarding problems never fail enable.
var runEnableOnboarding = func(ctx context.Context, w io.Writer, o enableOnboardingOpts) {
	// The user explicitly asked for setup — retry probes that recently
	// failed instead of serving the cached failure (which would silently
	// suppress the mirror offer for the rest of the failure TTL).
	defaultMirrorProbeCache().clearUnreachable()
	r := newEnableOnboardingRunner(w, o)
	fmt.Fprintln(w)
	r.run(ctx, w)
}

// newOnboardingOfferRunner wires the production runner: real rung probes,
// the login/mirror/import offers, and huh-based prompts. w is enable's
// output writer — offers write their progress there. importScope narrows the
// import offer (nil = all agents with hooks installed).
func newOnboardingOfferRunner(w io.Writer, importScope []agent.Agent) onboardingOfferRunner {
	deps := newOnboardingRungDeps()
	return onboardingOfferRunner{
		deps: deps,
		offerFns: map[string]func(ctx context.Context, granular bool) error{
			onboarding.KeyAuth:   func(ctx context.Context, _ bool) error { return runOnboardingLogin(ctx, w) },
			onboarding.KeyMirror: func(ctx context.Context, _ bool) error { return runOnboardingMirrorCreate(ctx, w, deps) },
			onboarding.KeyImport: func(ctx context.Context, granular bool) error {
				return runOnboardingImport(ctx, w, granular, importScope)
			},
		},
		selfPrompting: map[string]bool{onboarding.KeyImport: true},
		canPrompt:     interactive.CanPromptInteractively,
		promptMode:    promptOnboardingSetupMode,
		confirmRung:   confirmOnboardingRung,
		styles:        newStatusStyles,
	}
}

// promptOnboardingSetupMode is enable's single consent prompt, summarizing
// what "finish setup" will do from the missing rungs.
func promptOnboardingSetupMode(ctx context.Context, missing []onboarding.Result) (onboardingSetupMode, error) {
	summary := onboardingSetupSummary(missing)
	mode := setupModeAll
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[onboardingSetupMode]().
				Title("Finish setup?").
				Description(summary).
				Options(
					huh.NewOption("Yes, set up everything (recommended)", setupModeAll),
					huh.NewOption("Choose step by step", setupModeStepByStep),
					huh.NewOption("Skip for now — finish anytime with `entire enable`", setupModeSkip),
				).
				Value(&mode),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		return setupModeSkip, fmt.Errorf("setup consent prompt: %w", err)
	}
	return mode, nil
}

// onboardingSetupSummary describes what the fast path will do, e.g.
// "Logs in to entire.io and mirrors this repo so your work shows up in the
// web UI."
func onboardingSetupSummary(missing []onboarding.Result) string {
	steps := make([]string, 0, len(missing))
	for _, r := range missing {
		switch r.Rung.Key {
		case onboarding.KeyAuth:
			steps = append(steps, "logs in to entire.io")
		case onboarding.KeyMirror:
			steps = append(steps, "mirrors this repo")
		case onboarding.KeyImport:
			steps = append(steps, "imports existing agent history")
		}
	}
	if len(steps) == 0 {
		return ""
	}
	summary := formatTokenClassList(steps)
	// Capitalize the first step: summaries are full sentences in the prompt.
	return strings.ToUpper(summary[:1]) + summary[1:] + " so your work shows up in the web UI."
}

func confirmOnboardingRung(ctx context.Context, r onboarding.Result) (bool, error) {
	title := r.Rung.Title
	if r.Check.Detail != "" {
		title += " — " + r.Check.Detail
	}
	confirmed := true
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(title).
				Value(&confirmed),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		return false, fmt.Errorf("rung confirm prompt: %w", err)
	}
	return confirmed, nil
}

