14	// importScanCache memoizes the import rung's dry-run scan, which reads and
15	// parses every discovered transcript file. Invalidation is exact rather than
16	// TTL-based: the cache key fingerprints the discovered files' identity
17	// (path, mtime, size) plus the local metadata-branch tip, so an appended
18	// transcript or a new checkpoint/import (ref moves) recomputes immediately,
19	// while an unchanged repo pays only the cheap discovery glob on hot paths
20	// like `entire status`. Persistence via the shared jsonFileCache shell.
21	type importScanCache struct {
22		path string
23	}
24	
25	func defaultImportScanCache() importScanCache {
26		return importScanCache{path: filepath.Join(userdirs.Cache(), "onboarding_imports.json")}
27	}
28	
29	// importScanInput is one discovered transcript file's cache-relevant identity.
30	type importScanInput struct {
31		Path    string
32		ModTime time.Time
33		Size    int64
34	}
35	
36	// importScanFingerprint hashes the scan inputs order-independently.
